import{_ as t,o as s,c as d,a2 as a}from"./chunks/framework.B2iPdV6-.js";const g=JSON.parse('{"title":"配置（gflags）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/configuration.md","filePath":"zh/guide/configuration.md","lastUpdated":1790931789000}'),i={name:"zh/guide/configuration.md"};function o(l,e,n,c,r,h){return s(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="配置-gflags" tabindex="-1">配置（gflags） <a class="header-anchor" href="#配置-gflags" aria-label="Permalink to &quot;配置（gflags）&quot;">​</a></h1><p>NeoFlux 使用 <a href="https://github.com/gflags/gflags" target="_blank" rel="noreferrer">gflags</a> 做运行时配置，用 <a href="https://github.com/google/glog" target="_blank" rel="noreferrer">glog</a> 记录日志。下列参数均为可选，在命令行传入：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\build\\bin\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">neoflux_app.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">render_backend</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">target_fps</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">120</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">logtostderr</span></span></code></pre></div><h2 id="完整参数表" tabindex="-1">完整参数表 <a class="header-anchor" href="#完整参数表" aria-label="Permalink to &quot;完整参数表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>默认值</th><th>含义</th></tr></thead><tbody><tr><td><code>--render_backend</code></td><td><code>string</code></td><td><code>&quot;gl&quot;</code></td><td>选择 tgfx 渲染后端。本构建仅 <code>gl</code> 可用；<code>vulkan</code>、<code>cpu</code> 及任何未知值都是启动期硬错误（不静默回退）。</td></tr><tr><td><code>--target_fps</code></td><td><code>int32</code></td><td><code>60</code>（来自 <code>config::kDefaultTargetFps</code>）</td><td>应用事件循环的目标帧率。</td></tr><tr><td><code>--render_queue_capacity</code></td><td><code>uint64</code></td><td><code>2048</code>（来自 <code>config::kDefaultRenderQueueCapacity</code>）</td><td>SPSC 渲染命令环形队列容量，内部向上取整为 2 的幂（<code>std::bit_ceil</code>）；保留一个槽位，可用命令数 = <code>capacity - 1</code>。</td></tr><tr><td><code>--render_queue_drop_log_max</code></td><td><code>int32</code></td><td><code>10</code></td><td>每个进程最多打印多少次&quot;渲染队列已满、丢弃命令&quot;警告。超过后静默统计，不再刷屏。仅在诊断背压时调大。</td></tr><tr><td><code>--verbose_logging</code></td><td><code>bool</code></td><td><code>false</code></td><td>开启 <code>VLOG(1)</code> 并把 INFO 日志镜像到 stderr。</td></tr><tr><td><code>--logtostderr</code></td><td><code>bool</code></td><td><code>false</code></td><td>开启后所有日志写到 stderr 而非文件。</td></tr><tr><td><code>--log_dir</code></td><td><code>string</code></td><td><code>&quot;./logs&quot;</code></td><td><code>.log</code> 文件目录（自动创建），仅在未开启 <code>--logtostderr</code> 时生效。</td></tr><tr><td><code>--media_source</code></td><td><code>string</code></td><td><code>&quot;./assets/media/sample.mp4&quot;</code></td><td><code>/media</code> 路由中演示 <code>MediaWidget</code> 的视频路径或 URL。</td></tr></tbody></table><h3 id="render-backend" tabindex="-1"><code>--render_backend</code> <a class="header-anchor" href="#render-backend" aria-label="Permalink to &quot;`--render_backend`&quot;">​</a></h3><p>定义于 <code>neoflux/src/renderers/render_layer.cpp</code>，默认值为 <code>&quot;gl&quot;</code>。<strong>不存在静默 回退</strong>：请求不可用的后端会让 <code>RenderLayer::Start()</code> 记录错误并返回 <code>false</code>， 应用直接拒绝启动，而不是悄悄换成错误的后端渲染。</p><table tabindex="0"><thead><tr><th>取值</th><th>行为</th></tr></thead><tbody><tr><td><code>gl</code>（默认）</td><td>当前可用的桌面路径：tgfx OpenGL（WGL），经 GLFW 桥驱动。</td></tr><tr><td><code>vulkan</code></td><td>仅当 tgfx 以 <code>TGFX_USE_VULKAN=ON</code> 构建且本机存在 Vulkan 设备/驱动时可用；GL-only 构建下属于启动硬错误。</td></tr><tr><td><code>cpu</code></td><td>拒绝。tgfx 没有软件光栅化器，不存在 CPU 后端可回退。</td></tr><tr><td>其它任何值</td><td>视为未知值，拒绝启动。</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>当前桌面构建只有 <code>gl</code>。显式传 <code>--render_backend=gl</code> 表明意图；不要以为其它取值 会悄悄生效。</p></div><h3 id="target-fps" tabindex="-1"><code>--target_fps</code> <a class="header-anchor" href="#target-fps" aria-label="Permalink to &quot;`--target_fps`&quot;">​</a></h3><p>设置 <code>EventLoop::SetTargetFps()</code>。循环在帧之间睡眠以满足帧率上限；输入事件与 <code>MarkFrameDirty()</code> 会提前唤醒。默认 <code>60</code>。</p><h3 id="render-queue-capacity" tabindex="-1"><code>--render_queue_capacity</code> <a class="header-anchor" href="#render-queue-capacity" aria-label="Permalink to &quot;`--render_queue_capacity`&quot;">​</a></h3><p>配置 <code>RenderLayer</code> 构造的 <code>SpscRingQueue&lt;RenderCommand&gt;</code>。内部用 <code>std::bit_ceil</code> 向上取整为 2 的幂，使下标回绕可用按位与完成。因保留一个槽位区分满/空，请求 <code>2048</code> 实际最多存 <code>2047</code> 条在途命令。若生产者追上消费者，本帧多余命令被丢弃 （限频警告）。</p><div class="warning custom-block"><p class="custom-block-title">仅在出现”render command queue full”警告时再调大</p><p>队列越大越占内存、增加呈现延迟。默认 <code>2048</code> 对一般 widget 树已足够。</p></div><h3 id="render-queue-drop-log-max" tabindex="-1"><code>--render_queue_drop_log_max</code> <a class="header-anchor" href="#render-queue-drop-log-max" aria-label="Permalink to &quot;`--render_queue_drop_log_max`&quot;">​</a></h3><p>渲染命令队列满载丢帧时，NeoFlux 会打一条 <code>WARNING</code> 日志。为避免在持续 背压下刷屏，每个进程最多打印前 <code>N</code> 条丢帧警告，之后的丢弃被静默计数。 默认 <code>10</code>。设为 <code>0</code> 可完全关闭丢帧警告。</p><h3 id="media-source" tabindex="-1"><code>--media_source</code> <a class="header-anchor" href="#media-source" aria-label="Permalink to &quot;`--media_source`&quot;">​</a></h3><p>传给 <code>/media</code> 路由上内置 demo <code>MediaWidget</code> 的路径或 URL。默认 <code>./sample.mp4</code>。这个参数仅用于让 quick-start 应用不用重编译就能指向测试 视频；真实应用自己构造 <code>MediaWidget</code> 并直接调 <code>SetSource()</code>。</p><h3 id="verbose-logging" tabindex="-1"><code>--verbose_logging</code> <a class="header-anchor" href="#verbose-logging" aria-label="Permalink to &quot;`--verbose_logging`&quot;">​</a></h3><p>一个便捷开关。开启后 NeoFlux 打开 <code>VLOG(1)</code>（<code>FLAGS_v = 1</code>）并把 INFO 级日志镜像到 stderr。逐帧布局转储（<code>VLOG(1) &lt;&lt; widgetname [x y w h]</code>）就靠它显示。</p><h3 id="logtostderr" tabindex="-1"><code>--logtostderr</code> <a class="header-anchor" href="#logtostderr" aria-label="Permalink to &quot;`--logtostderr`&quot;">​</a></h3><p>这是 glog 内建参数。当 glog 未与 gflags 集成构建时，NeoFlux 会在 gflags 解析之前 预扫描 <code>argv</code>，识别 <code>--logtostderr</code> / <code>--nologtostderr</code>（及 <code>-</code> 短横线形式）。默认关闭， 日志写入文件。</p><h3 id="log-dir" tabindex="-1"><code>--log_dir</code> <a class="header-anchor" href="#log-dir" aria-label="Permalink to &quot;`--log_dir`&quot;">​</a></h3><p>同样是 glog 内建参数，由同一套 argv 预扫描处理。同时接受 <code>--log_dir=路径</code> 与 <code>--log_dir 路径</code> 两种写法。写文件时默认 <code>./logs</code>，自动建目录，并追加 <code>.log</code> 扩展名； 目录无法创建时静默回退到 stderr。</p><h2 id="代码里打日志" tabindex="-1">代码里打日志 <a class="header-anchor" href="#代码里打日志" aria-label="Permalink to &quot;代码里打日志&quot;">​</a></h2><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;glog/logging.h&gt;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LOG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(INFO) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Application started&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LOG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(WARNING) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Font not found, using default&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LOG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ERROR) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Rendering failed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">VLOG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Detailed per-frame debug info&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 配 --verbose_logging 显示</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">推荐的开发命令</p><p>本应用是 GUI 子系统二进制、没有控制台，运行时建议：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\build\\bin\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">neoflux_app.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">logtostderr </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">verbose_logging</span></span></code></pre></div></div><h2 id="完整示例" tabindex="-1">完整示例 <a class="header-anchor" href="#完整示例" aria-label="Permalink to &quot;完整示例&quot;">​</a></h2><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\build\\bin\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">neoflux_app.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> `</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">target_fps</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">144</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> `</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">render_backend</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">`</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">render_queue_capacity</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4096</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> `</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">logtostderr </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">`</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">verbose_logging</span></span></code></pre></div><p>即目标 144 FPS、使用 GL 后端、队列扩到 4096，并把详细日志输出到终端。</p><h2 id="编译时常量-core-config-h" tabindex="-1">编译时常量（<code>core/config.h</code>） <a class="header-anchor" href="#编译时常量-core-config-h" aria-label="Permalink to &quot;编译时常量（`core/config.h`）&quot;">​</a></h2><p>部分值是<strong>编译期</strong>的（编入二进制，不能运行时改）。它们定义在 <code>neoflux/include/neoflux/core/config.h</code> 中，为 <code>inline constexpr</code>：</p><table tabindex="0"><thead><tr><th>常量</th><th>默认值</th><th>含义</th></tr></thead><tbody><tr><td><code>config::kCacheLineSize</code></td><td><code>64</code></td><td>CPU 缓存行字节数。用于 SPSC 队列头尾分占不同缓存行（避免伪共享）。Apple M 系列/新 AMD 可用 <code>-DNEOFLUX_CACHE_LINE_SIZE=128</code> 覆盖。</td></tr><tr><td><code>config::kDefaultRenderQueueCapacity</code></td><td><code>2048</code></td><td><code>--render_queue_capacity</code> 的默认值。</td></tr><tr><td><code>config::kDefaultTargetFps</code></td><td><code>60</code></td><td><code>--target_fps</code> 的默认值。</td></tr><tr><td><code>config::kLongPressThresholdMs</code></td><td><code>500</code></td><td><code>Button</code> 长按检测阈值（毫秒）。</td></tr><tr><td><code>config::kFlingStopThreshold</code></td><td><code>0.02</code></td><td>惯性滑动停止阈值（屏幕高度/秒）。</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">gflag 默认值跟随 config.h</p><p>gflag 定义使用这些常量作为默认值。改 <code>config.h</code> 里的 <code>kDefaultTargetFps</code> 为 30 并重新编译，<code>--target_fps</code> 的默认值自动变成 30，无需修改 flag 定义。</p></div>',34)])])}const k=t(i,[["render",o]]);export{g as __pageData,k as default};
